async function openDB(name){return new Promise((resolve,reject)=>{const r=indexedDB.open(name);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function mutateDB(name,store,work){const db=await openDB(name);try{await new Promise((resolve,reject)=>{const tx=db.transaction(store,'readwrite');work(tx.objectStore(store));tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);});}finally{db.close();}}
