const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
async function alterGenerationAssets(file,change){const magic=new TextEncoder().encode('BREDITOR-GENERATION-ASSETS1\n'),prefix=new Uint8Array(await file.slice(0,magic.length+4).arrayBuffer()),length=new DataView(prefix.buffer).getUint32(magic.length),header=JSON.parse(await file.slice(prefix.length,prefix.length+length).text()),payload=new Uint8Array(await file.slice(prefix.length+length).arrayBuffer());change(header,payload);const body={format:header.format,formatVersion:header.formatVersion,metadata:header.metadata,records:header.records,assets:header.assets},encoded=new TextEncoder().encode(JSON.stringify({...body,sha256:hash(JSON.stringify(body))}));new DataView(prefix.buffer).setUint32(magic.length,encoded.length);return new Blob([prefix,encoded,payload]);}
